import{_ as t,o,c as a,ae as i}from"./chunks/framework.B2FZg54p.js";const r="/heidrun/experiments/web-doc-by-ai/documentation_images/files/copy_path.png",u=JSON.parse('{"title":"Copy a file path","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/copy_a_file_path.md","filePath":"documentation/copy_a_file_path.md"}'),l={name:"documentation/copy_a_file_path.md"};function n(s,e,h,p,c,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="copy-a-file-path" tabindex="-1">Copy a file path <a class="header-anchor" href="#copy-a-file-path" aria-label="Permalink to &quot;Copy a file path&quot;">​</a></h1><p>Copy a file path to paste into another application or a message.</p><h2 id="choose-the-path-format" tabindex="-1">Choose the path format <a class="header-anchor" href="#choose-the-path-format" aria-label="Permalink to &quot;Choose the path format&quot;">​</a></h2><p>An absolute path gives the full location on your computer; a relative path starts at the Git repository root, the folder that contains the whole repository. For a repository at <code>/Users/alex/projects/example</code> and a workspace at <code>/Users/alex/projects/example/docs</code>, copying the workspace&#39;s <code>README.md</code> gives these two forms.</p><table tabindex="0"><thead><tr><th>Choice</th><th>Example</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Copy absolute path</strong></td><td><code>/Users/alex/projects/example/docs/README.md</code></td><td>The receiving application needs the full location on your computer.</td></tr><tr><td><strong>Copy relative path</strong></td><td><code>docs/README.md</code></td><td>The receiving application or reader already knows the Git repository root.</td></tr></tbody></table><h2 id="copy-the-path" tabindex="-1">Copy the path <a class="header-anchor" href="#copy-the-path" aria-label="Permalink to &quot;Copy the path&quot;">​</a></h2><p>First, <a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html#select-an-existing-workspace">select an existing workspace</a>.</p><ol><li>Click <strong>Files</strong>, the first folder icon in the left sidebar icon bar, above <strong>Scripts</strong>, and click the containing folder rows to unfold the folders and locate the file.</li><li>Right-click the file row to open the context menu, a small menu of actions for the file. A left click opens the large Git window; you can right-click directly to copy the path.</li></ol><p><img src="'+r+'" alt="Files sidebar section with docs unfolded, docs/README.md selected, and Copy absolute path and Copy relative path in the context menu."></p><ol start="3"><li>Choose <strong>Copy absolute path</strong> or <strong>Copy relative path</strong>, using the table above.</li></ol><p>The path is copied, the context menu closes, and a small notification briefly shows <strong>Copied:</strong> followed by the copied path, for example <code>Copied: docs/README.md</code>.</p><ol start="4"><li>Paste the path in the other application with <strong>⌘V</strong>.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="The path-copy menu does not appear when a folder row is right-clicked"><h3 id="the-path-copy-menu-does-not-appear-when-a-folder-row-is-right-clicked" tabindex="-1">The path-copy menu does not appear when a folder row is right-clicked <a class="header-anchor" href="#the-path-copy-menu-does-not-appear-when-a-folder-row-is-right-clicked" aria-label="Permalink to &quot;The path-copy menu does not appear when a folder row is right-clicked&quot;">​</a></h3><p><strong>Cause</strong>: The path-copy context menu is available only for file rows.</p><p><strong>Solution</strong>:</p><ol><li>Click the folder row to unfold the folder if necessary.</li><li>Right-click a file row inside the folder.</li></ol><p><strong>Check</strong>: The context menu shows <strong>Copy absolute path</strong> and <strong>Copy relative path</strong>.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html">Browse and open project files</a>: to find the file whose path you need.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/create_a_file_or_folder.html">Create a file or folder</a>: to add a file before copying the file path.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/files_sidebar_section_controls.html#file-context-menu">File context menu</a>: to look up the two path-copy actions.</li></ul>',16)])])}const m=t(l,[["render",n]]);export{u as __pageData,m as default};
